import * as THREE from 'three';

const inRoom = (room, p) => Math.abs(p.x-room.x)<=room.width/2 && Math.abs(p.z-room.z)<=room.depth/2;
function thresholdDistance(door, position) {
  const [a,b]=door.points, dx=b[0]-a[0], dz=b[1]-a[1];
  const t=Math.max(0,Math.min(1,((position.x-a[0])*dx+(position.z-a[1])*dz)/Math.max(.001,dx*dx+dz*dz)));
  return Math.hypot(position.x-a[0]-t*dx,position.z-a[1]-t*dz);
}

// Zero-intensity lights still enlarge Three's lighting shader. Bound both the
// room count and fixture count, including the all-form study room. Ambient and
// environment light cover the room while nearby works receive local accents.
export function createExhibitionLighting(scene, plan, fixtures) {
  const groups=new Map(plan.rooms.map(room=>[room.index,fixtures.filter(f=>f.roomIndex===room.index)]));
  const capacity=Math.min(4,Math.max(0,...[...groups.values()].map(group=>group.length)));
  const banks=Array.from({length:Math.min(2,plan.rooms.length)},()=>({roomIndex:null,strength:0,slots:Array.from({length:capacity},()=>{
    const light=new THREE.SpotLight('#fff0df',0,13,Math.PI*.34,1,2);
    scene.add(light,light.target);return {light,fixture:null,strength:0};
  })}));
  const state={level:1};
  let initial=true, activeDoor=null;
  return {
    state,
    update(position,dt,instant=false) {
      const current=plan.rooms.find(room=>inRoom(room,position));
      const candidates=plan.doors.filter(door=>!current||door.a===current.index||door.b===current.index);
      const nearest=candidates.slice().sort((a,b)=>thresholdDistance(a,position)-thresholdDistance(b,position))[0];
      if(nearest&&thresholdDistance(nearest,position)<=5.2)activeDoor=nearest;
      else if(!candidates.includes(activeDoor)||thresholdDistance(activeDoor,position)>6.4)activeDoor=null;
      const desired=new Set(activeDoor?[activeDoor.a,activeDoor.b]:current?[current.index]:[]);
      // The opening gallery is part of the entrance view, even before the
      // visitor approaches its doorway. Both rooms are lit from the first frame.
      if(current?.index===0&&plan.rooms[1]){desired.clear();desired.add(0);desired.add(1);}
      let changing=false;
      for(const bank of banks) {
        const wanted=desired.has(bank.roomIndex);
        const amount=instant||initial?1:dt/(wanted?.65:.3);
        bank.strength=THREE.MathUtils.clamp(bank.strength+(wanted?amount:-amount),0,1);
        if(!wanted&&bank.strength===0) {
          const used=new Set(banks.map(other=>other.roomIndex));
          bank.roomIndex=[...desired].find(index=>!used.has(index))??null;
          bank.slots.forEach(slot=>{slot.fixture=null;slot.strength=0;});
          if((instant||initial)&&bank.roomIndex!==null)bank.strength=1;
        }
        if(bank.strength!==Number(desired.has(bank.roomIndex)))changing=true;
        const group=groups.get(bank.roomIndex)||[];
        const retained=new Set(bank.slots.map(slot=>slot.fixture));
        const distance=fixture=>Math.hypot(fixture.target[0]-position.x,fixture.target[2]-position.z)-(retained.has(fixture)?.8:0);
        const selected=new Set(group.slice().sort((a,b)=>distance(a)-distance(b)).slice(0,capacity));
        for(const slot of bank.slots) {
          const selectedHere=selected.has(slot.fixture);
          slot.strength=THREE.MathUtils.clamp(slot.strength+(selectedHere?1:-1)*(instant||initial?1:dt/.25),0,1);
          // Move a light only after its previous pool has faded out. Existing
          // neighbours stay lit throughout a new fixture's arrival.
          if(!selectedHere&&slot.strength===0) {
            const used=new Set(bank.slots.map(other=>other.fixture));
            slot.fixture=[...selected].find(fixture=>!used.has(fixture))||null;
            if(slot.fixture) {
              slot.light.position.fromArray(slot.fixture.eye);
              slot.light.target.position.fromArray(slot.fixture.target);
              if(instant||initial)slot.strength=1;
            }
          }
          if(slot.strength!==Number(selected.has(slot.fixture)))changing=true;
          slot.light.intensity=(slot.fixture?.power||0)*slot.strength*bank.strength*state.level;
        }
      }
      initial=false;
      return changing;
    },
    dispose(){for(const bank of banks)for(const {light} of bank.slots){scene.remove(light,light.target);light.dispose();}},
  };
}

export function exhibitionLightFixture(anchor,rotation=0,power=85,roomIndex=0) {
  return {roomIndex,eye:[anchor[0]+Math.sin(rotation)*2.3,5.3,anchor[2]+Math.cos(rotation)*2.3],target:[anchor[0],Math.min(anchor[1],2.4),anchor[2]],power};
}
